import pandas as pd# --- 1. Read in the dataset ---df = pd.read_excel("matches-with-embargo-end-dates.xlsx")# --- 2. Drop any rows where 'File Count' is less than 4 ---rows_before_filecount = len(df)df = df[df["File Count"] >= 4].copy()rows_after_filecount = len(df)print(f"Rows removed due to File Count filter: {rows_before_filecount - rows_after_filecount}")# --- 3. Drop any rows where 'Embargo Release' is after today's date ---# Rows with a blank/missing Embargo Release are treated as not embargoed and are kept.# Today's date is 8/5/2026df["Embargo Release"] = pd.to_datetime(df["Embargo Release"], errors="coerce")today = pd.Timestamp.now().normalize()  # today's date, time stripped to midnightrows_before = len(df)mask_future_embargo = df["Embargo Release"].notna() & (df["Embargo Release"] > today)df = df[~mask_future_embargo].copy()rows_after = len(df)print(f"Rows removed due to embargo release filter: {rows_before - rows_after}")# --- 4. Make separate groups of files by year ---# 'Published Date' looks like '2021-05-13', so we extract the year from it.df["Year"] = pd.to_datetime(df["Published Date"]).dt.year# groupby object: lets you loop over (year, sub-dataframe) pairsgroups_by_year = df.groupby("Year")# Option A: dict of {year: dataframe} for direct indexing, e.g. yearly_data[2023]yearly_data = {year: group for year, group in groups_by_year}# Example usage:for year, group_df in yearly_data.items():    print(f"Year {year}: {len(group_df)} rows")# --- 5. Take a random 10% sample of rows within each year group ---# random_state fixes the seed so results are reproducible; drop it (or change it) for a different sample each run.sampled_by_year = {    year: group_df.sample(frac=0.10, random_state=42)    for year, group_df in yearly_data.items()}for year, sample_df in sampled_by_year.items():    print(f"Year {year}: sampled {len(sample_df)} of {len(yearly_data[year])} rows")# Combine all yearly samples back into one dataframe, if usefulsampled_all = pd.concat(sampled_by_year.values(), ignore_index=True)# --- 6. Save each year's sample as its own file: '{year}_randomsample.xlsx' ---for year, sample_df in sampled_by_year.items():    sample_df.to_excel(f"{year}_randomsample.xlsx", index=False)                                                